import unittest
from renames.validation import rename_map
from renames.operations import apply_renames

class ProjectTests(unittest.TestCase):
    def test_simultaneous_swap(self):
        original = {'a': 1, 'b': 2, 'c': 3}
        changes = [{'source': 'a', 'target': 'b'}, {'source': 'b', 'target': 'a'}]
        self.assertEqual(list(apply_renames(original, changes).items()), [('b', 1), ('a', 2), ('c', 3)])
        self.assertEqual(original, {'a': 1, 'b': 2, 'c': 3})

    def test_chain_and_self(self):
        self.assertEqual(apply_renames({'a': 1, 'b': 2}, [{'source': 'a', 'target': 'b'}, {'source': 'b', 'target': 'c'}]), {'b': 1, 'c': 2})
        self.assertEqual(rename_map({'a': 1}, [{'source': 'a', 'target': 'a'}]), {'a': 'a'})
        self.assertEqual(apply_renames({}, []), {})

    def test_invalid_batch(self):
        for changes in ([{'source': 'z', 'target': 'a'}], [{'source': 'a', 'target': 'b'}], [{'source': 'a', 'target': 'x'}, {'source': 'a', 'target': 'y'}], [{'source': 'a', 'target': 'x'}, {'source': 'b', 'target': 'x'}]):
            with self.subTest(changes=changes), self.assertRaises(ValueError):
                apply_renames({'a': 1, 'b': 2}, changes)

    def test_container_types_even_when_empty(self):
        for fn in (rename_map, apply_renames):
            for registry in (None, [], {'': 1}, {1: 2}):
                self.assert_invalid(fn, registry, [])
            for changes in (None, {}, (), ({'source': 'a', 'target': 'x'},)):
                self.assert_invalid(fn, {'a': 1}, changes)

    def test_change_fields_raise_value_error(self):
        for change in (None, {}, {'source': 'a'}, {'source': 'a', 'target': []}):
            for fn in (rename_map, apply_renames):
                self.assert_invalid(fn, {'a': 1}, [change])

    def assert_invalid(self, fn, *args):
        try:
            result = fn(*args)
        except ValueError:
            return
        except Exception as error:
            raise AssertionError(f'{fn.__name__}{args!r}: expected ValueError, got {type(error).__name__}') from None
        self.fail(f'{fn.__name__}{args!r}: accepted {result!r}; expected ValueError')

