import unittest
from windows.ranges import parse_range
from windows.response import serve

class ProjectTests(unittest.TestCase):
    def test_ranges(self):
        self.assertEqual(parse_range('bytes=1-3', 6), (1, 3))
        self.assertEqual(parse_range('bytes=3-', 6), (3, 5))
        self.assertEqual(parse_range('bytes=-2', 6), (4, 5))
        self.assertEqual(parse_range('bytes=2-99', 6), (2, 5))

    def test_response(self):
        self.assertEqual(serve(b'abcdef', 'bytes=1-3'), {'status': 206, 'body': b'bcd', 'content_range': 'bytes 1-3/6'})
        self.assertEqual(serve(b''), {'status': 200, 'body': b'', 'content_range': None})

    def test_invalid(self):
        for header in ('bytes=3-1', 'bytes=6-', 'bytes=-0', 'bytes=-', 'bytes=0-1,3-4'):
            with self.subTest(header=header), self.assertRaises(ValueError):
                parse_range(header, 6)

    def test_header_and_size_types(self):
        for header in (None, 1, [], b'bytes=0-1'):
            self.assert_invalid(parse_range, header, 6)
        for size in (0, -1, True, False, 1.5, '6', None):
            self.assert_invalid(parse_range, 'bytes=0-0', size)

    def test_response_input_types(self):
        for data in ('abc', bytearray(b'abc'), None, []):
            for header in (None, 'bytes=0-0'):
                self.assert_invalid(serve, data, header)
        for header in (1, [], b'bytes=0-1'):
            self.assert_invalid(serve, b'abcdef', header)

    def test_range_grammar_is_ascii_and_exact(self):
        for header in ('bytes=١-3', 'bytes=1-３', 'bytes=١-', 'bytes=-٣',
                       'bytes=0-1\n', 'bytes=0-1 ', 'bytes=+1-2'):
            self.assert_invalid(parse_range, header, 6)
            self.assert_invalid(serve, b'abcdef', header)

    def assert_invalid(self, fn, *args):
        try:
            result = fn(*args)
        except ValueError:
            return
        except Exception as error:
            raise AssertionError(f'{fn.__name__}{args!r}: expected ValueError, got {type(error).__name__}') from None
        self.fail(f'{fn.__name__}{args!r}: accepted {result!r}; expected ValueError')
    def test_empty_header_is_not_missing(self):
        self.assert_invalid(parse_range, '', 3)
        for data in (b'', b'abc'):
            self.assertEqual(serve(data, None), {'status': 200, 'body': data, 'content_range': None})
            self.assert_invalid(serve, data, '')

