import unittest
from events.validation import normalize
from events.replay import replay

def put(identity, version, value=1, key='a'):
    return {'id': identity, 'key': key, 'version': version, 'action': 'put', 'value': value}

class ProjectTests(unittest.TestCase):
    def test_replay_and_duplicate(self):
        first, second = put('1', 1), put('2', 3, 5)
        self.assertEqual(replay([first, second, first]), {'values': {'a': 5}, 'versions': {'a': 3}})
        self.assertEqual(replay([]), {'values': {}, 'versions': {}})

    def test_delete_missing_and_existing(self):
        delete = {'id': 'd', 'key': 'a', 'version': 5, 'action': 'delete'}
        self.assertEqual(replay([delete]), {'values': {}, 'versions': {'a': 5}})
        self.assertEqual(replay([put('1', 1), delete]), {'values': {}, 'versions': {'a': 5}})

    def test_invalid_sequences(self):
        for stream in ([put('1', 2), put('2', 1)], [put('1', 2), put('2', 2)], [put('1', 1), put('1', 1, 9)]):
            with self.subTest(stream=stream), self.assertRaises(ValueError):
                replay(stream)
        with self.assertRaises(ValueError):
            normalize({'id': 'x', 'key': 'a', 'version': 1, 'action': 'put'})

    def test_stream_requires_list(self):
        for stream in (None, {}, (), (put('1', 1),), ''):
            self.assert_invalid(replay, stream)

    def test_normalized_delete_has_no_value_or_extra_fields(self):
        delete = {'id': 'd', 'key': 'a', 'version': 5, 'action': 'delete'}
        raw = dict(delete, extra='ignored')
        result = normalize(raw)
        self.assertEqual(result, delete)
        self.assertIsNot(result, raw)
        self.assertEqual(raw, dict(delete, extra='ignored'))
        self.assert_invalid(normalize, dict(delete, value=None))
        self.assertEqual(normalize(put('nil', 1, None)), put('nil', 1, None))

    def test_invalid_event_fields_raise_value_error(self):
        for event in (None, [], {}, dict(put('1', 1), version=True), dict(put('1', 1), action=[])):
            self.assert_invalid(normalize, event)
            self.assert_invalid(replay, [event])

    def assert_invalid(self, fn, *args):
        try:
            result = fn(*args)
        except ValueError:
            return
        except Exception as error:
            raise AssertionError(f'{fn.__name__}{args!r}: expected ValueError, got {type(error).__name__}') from None
        self.fail(f'{fn.__name__}{args!r}: accepted {result!r}; expected ValueError')

