import unittest
from arguments.lexing import split_words
from arguments.options import parse_assignments

class ProjectTests(unittest.TestCase):
    def test_quotes_and_escapes(self):
        self.assertEqual(split_words('one "two three" four\\ five'), ['one', 'two three', 'four five'])
        self.assertEqual(split_words("ab'cd ef'gh"), ['abcd efgh'])
        self.assertEqual(split_words(''), [])

    def test_assignments(self):
        self.assertEqual(parse_assignments('A=one B="two three" EQ=x=y A=last'), {'A': 'last', 'B': 'two three', 'EQ': 'x=y'})
        self.assertEqual(parse_assignments('EMPTY= _X2=yes'), {'EMPTY': '', '_X2': 'yes'})

    def test_invalid(self):
        for text in ('A', '=x', '1A=x', 'A="unfinished'):
            with self.subTest(text=text), self.assertRaises(ValueError):
                parse_assignments(text)

    def test_empty_words_and_adjacent_fragments(self):
        cases = [('""', ['']), ("''", ['']), ('left "" right', ['left', '', 'right']),
                 ('""""', ['']), ('a""b', ['ab']), ('  \t\r\n', [])]
        for text, expected in cases:
            with self.subTest(text=text):
                self.assertEqual(split_words(text), expected)
        for text in ('""', "''", 'A=ok ""'):
            self.assert_invalid(parse_assignments, text)

    def test_input_types_raise_value_error(self):
        for fn in (split_words, parse_assignments):
            for text in (None, [], 1, True, b'A=one'):
                self.assert_invalid(fn, text)

    def test_escape_and_quote_errors(self):
        for text in ('"open', "'open", 'word' + chr(92), '"word' + chr(92)):
            self.assert_invalid(split_words, text)
        self.assertEqual(split_words("'a" + chr(92) + "b'"), ['a' + chr(92) + 'b'])
        self.assertEqual(split_words('"a' + chr(92) + 'qb"'), ['aqb'])

    def test_key_requires_full_ascii_match(self):
        for text in ('é=x', 'A-B=x'):
            self.assert_invalid(parse_assignments, text)

    def test_key_cannot_end_with_newline(self):
        # Both inputs lex correctly to one word; the resulting key is invalid.
        for text in ('A' + chr(92) + '\n=x', '"A\n"=x'):
            self.assertEqual(split_words(text), ['A\n=x'])
            self.assert_invalid(parse_assignments, text)

    def assert_invalid(self, fn, *args):
        try:
            result = fn(*args)
        except ValueError:
            return
        except Exception as error:
            raise AssertionError(f'{fn.__name__}{args!r}: expected ValueError, got {type(error).__name__}') from None
        self.fail(f'{fn.__name__}{args!r}: accepted {result!r}; expected ValueError')

    def test_unquoted_separators(self):
        self.assertEqual(split_words('alpha beta\tgamma\rdelta\nomega'),
                         ['alpha', 'beta', 'gamma', 'delta', 'omega'])
        self.assertEqual(split_words('  first  second  '), ['first', 'second'])

    def test_quoted_newline_is_literal(self):
        for text in ('"a\nb"', "'a\nb'"):
            with self.subTest(text=text):
                self.assertEqual(split_words(text), ['a\nb'])
    def test_repeated_key_keeps_first_position(self):
        result = parse_assignments('Z=old A=one Z=new M=two A=last')
        self.assertEqual(list(result.items()), [('Z', 'new'), ('A', 'last'), ('M', 'two')],
                         'Replacing a value must keep the first occurrence of its key in place')
